1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	
14	/**
15	 * The MHPCO price list prices each main item type by its own tariff row, but
16	 * prices every component by one rule: 25 G per component, whatever its kind.
17	 */
18	const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	};
24	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
25	const COMPONENT_BASE_PREMIUM = 25;
26	
27	function isComponent(type: string): boolean {
28	  return COMPONENT_TYPES.has(type);
29	}
30	
31	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
32	const LOYALTY_DISCOUNT_PERCENT = 20;
33	const LOYALTY_YEARS = 2;
34	const PERCENT = 100;
35	
36	// Percentages are kept as exact fractions (integer numerator over PERCENT);
37	// scaling by a float rate such as 0.1 yields artefacts like 115.00000000000001.
38	function percentOf(amount: number, percent: number): number {
39	  return (amount * percent) / PERCENT;
40	}
41	
42	/** MHPCO rounds a premium up: every fraction of a G falls to the customer. */
43	function roundInMHPCOsFavor(premium: number): number {
44	  return Math.ceil(premium);
45	}
46	
47	const BLOCK_SIZE = 3;
48	const BLOCK_BASE_PREMIUM = 60;
49	
50	/**
51	 * Two items are "alike" when they share an item type -- not merely a family.
52	 * The price list settles this: 2 runes + 1 moonstone form no block (75 G), so
53	 * rune-y and gemstone-y kinship is not enough to build a block together.
54	 */
55	function alikeGroupKey(item: Item): string {
56	  return item.type;
57	}
58	
59	function countAlikeGroups(items: Item[]): Map<string, number> {
60	  const counts = new Map<string, number>();
61	  for (const item of items) {
62	    const key = alikeGroupKey(item);
63	    counts.set(key, (counts.get(key) ?? 0) + 1);
64	  }
65	  return counts;
66	}
67	
68	/**
69	 * A building block of exactly 3 alike components is offered at a special rate;
70	 * the block is not greedy, so 4 or 7 runes form no block at all.
71	 */
72	function componentGroupBasePremium(count: number): number {
73	  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
74	}
75	
76	/**
77	 * The price list quotes a group of alike items as a whole, because only a group
78	 * can qualify for the block rate. Main items have no group rate: they are priced
79	 * one by one.
80	 */
81	function alikeGroupBasePremium(type: string, count: number): number {
82	  return isComponent(type)
83	    ? componentGroupBasePremium(count)
84	    : count * MAIN_ITEM_BASE_PREMIUM[type];
85	}
86	
87	export function policyBasePremium(items: Item[]): number {
88	  let total = 0;
89	  for (const [type, count] of countAlikeGroups(items)) {
90	    total += alikeGroupBasePremium(type, count);
91	  }
92	  return total;
93	}
94	
95	const CURSE_SURCHARGE_PERCENT = 50;
96	const HIGH_ENCHANTMENT_LEVEL = 5;
97	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
98	
99	/** The threshold is inclusive: exactly enchantment 5 already counts as high. */
100	function isHighlyEnchanted(item: Item): boolean {
101	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
102	}
103	
104	/**
105	 * The risk the price list reads off a single item. The surcharges stack: an
106	 * item that carries several risks is charged for each of them.
107	 */
108	function itemRiskSurchargePercent(item: Item): number {
109	  const cursePercent = item.cursed === true ? CURSE_SURCHARGE_PERCENT : 0;
110	  const enchantmentPercent = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
111	  return cursePercent + enchantmentPercent;
112	}
113	
114	/**
115	 * The amount an item's own risk surcharges are charged on: its price-list row,
116	 * never the policy total. Components carry no risk of their own, and a blocked
117	 * component has no premium of its own to be surcharged -- so they contribute 0.
118	 */
119	function surchargeableBasePremium(item: Item): number {
120	  return isComponent(item.type) ? 0 : MAIN_ITEM_BASE_PREMIUM[item.type];
121	}
122	
123	function itemSurcharges(items: Item[]): number {
124	  return items.reduce(
125	    (total, item) =>
126	      total + percentOf(surchargeableBasePremium(item), itemRiskSurchargePercent(item)),
127	    0,
128	  );
129	}
130	
131	/** The threshold is inclusive: exactly 2 years already earns the discount. */
132	function isLongStanding(customer: Customer): boolean {
133	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
134	}
135	
136	/**
137	 * Policy-wide modifiers are all charged against the policy base premium, so the
138	 * MHPCO nets them into a single percentage: a long-standing customer earns a
139	 * discount, every quoted policy carries the first-insurance assessment.
140	 */
141	function policyWideModifierPercent(customer: Customer): number {
142	  const loyaltyPercent = isLongStanding(customer) ? -LOYALTY_DISCOUNT_PERCENT : 0;
143	  return FIRST_INSURANCE_SURCHARGE_PERCENT + loyaltyPercent;
144	}
145	
146	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
147	  // Item-specific modifiers are charged on the affected item's own base premium;
148	  // policy-wide modifiers are charged on the policy base premium, the plain sum
149	  // of all item base premiums -- never on a base that already carries item
150	  // surcharges. The processing fee is added at the very end, and only the final
151	  // premium is rounded: intermediate amounts stay fractional.
152	  const policyBase = policyBasePremium(items);
153	  const netPolicyModifierPercent = policyWideModifierPercent(customer);
154	  const policyModifiers = percentOf(policyBase, netPolicyModifierPercent);
155	  return roundInMHPCOsFavor(
156	    policyBase + itemSurcharges(items) + policyModifiers + PROCESSING_FEE,
157	  );
158	}
